pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C{value: 1 ether}();
    }

    function testFuzz_property(uint256 startBlock, address actor, bytes32 guess) public {
        vm.assume(actor != address(0));
        startBlock = bound(startBlock, 2, type(uint256).max - 2);

        vm.roll(startBlock);
        vm.deal(actor, 1 ether);
        vm.prank(actor);
        c.lockInGuess{value: 1 ether}(guess);

        // One block later: settle must still be disallowed, since the target
        // block recorded by lockInGuess is block.number + 1.
        vm.roll(startBlock + 1);
        vm.prank(actor);
        bool ok;
        try c.settle() {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(!ok);
    }
}

