pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C{value: 1 ether}(); }

    function testFuzz_property(address actor, bytes32 guess) public {
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));

        vm.deal(actor, 2 ether);
        vm.prank(actor);
        c.lockInGuess{value: 1 ether}(guess);

        // move past the locked block so settle can succeed
        uint256 target = vm.getBlockNumber() + 2;
        vm.roll(target);

        bool firstOk;
        try c.settle() { firstOk = true; } catch { firstOk = false; }
        assertTrue(firstOk, "first settle should succeed for any admissible input");

        // RULE: after a successful settle, the guess is cleared and settle must revert
        bool secondOk;
        try c.settle() { secondOk = true; } catch { secondOk = false; }
        assertTrue(!secondOk, "settle must be one-shot: second settle must revert");
    }
}

