pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C{value: 1 ether}();
    }

    function testFuzz_property(address actor, bytes32 g) public {
        vm.assume(actor != address(0));
        vm.assume(uint160(actor) > 100);

        // lock in a guess
        vm.deal(actor, 1 ether);
        vm.prank(actor);
        c.lockInGuess{value: 1 ether}(g);

        // jump so that the target block is in the past; in the test EVM the
        // blockhash of that block is 0, so a guess of bytes32(0) is a winner.
        uint256 target;
        // read the stored block via behavior: just roll far ahead twice
        vm.roll(block.number + 1);
        target = block.number; // this is lockInGuess block
        vm.roll(target + 1);

        // settle; reversion (insufficient 2-ether balance for a win) is fine
        vm.prank(actor);
        try c.settle() {
            // no revert
        } catch {
            // revert (e.g. correct guess with < 2 ether balance)
        }

        // General rule: c's balance is never reduced below its original 1 ether
        // by any settle: a win is impossible to pay (needs 2 ether) and a loss
        // pays nothing.
        assertTrue(address(c).balance == 1 ether);
    }
}

