pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C{value: 1 ether}(); }

    function testFuzz_property(address actor, uint256 rollAhead) public {
        // admissible domain: actor is a plain EOA distinct from c; we jump more
        // than 256 blocks ahead so blockhash(guesses.block) returns 0, making the
        // winning answer keccak256(bytes32(0)) — reachable for EVERY admissible input
        vm.assume(actor != address(0) && actor != address(c));
        actor = address(uint160(bound(uint160(actor), 1, type(uint160).max)));
        vm.assume(actor != address(c));
        rollAhead = bound(rollAhead, 257, 1000);

        // lock a guess that will be the winning answer after the block jump
        bytes32 g = keccak256(abi.encodePacked(bytes32(0)));
        vm.deal(actor, 1 ether);
        vm.prank(actor);
        c.lockInGuess{value: 1 ether}(g);

        // jump beyond the 256-block blockhash window: blockhash(guesses.block) == 0
        vm.roll(block.number + rollAhead);

        // settle as the winner; reference pays 2 ether (drains c), mutant pays 1
        vm.prank(actor);
        c.settle();

        // general rule: a completed winning settle always empties the contract
        assertTrue(address(c).balance == 0);
    }
}

