pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C{value: 1 ether}(); }

    function testFuzz_property(address actor, bytes32 salt) public {
        vm.assume(actor != address(0) && actor != address(c) && actor != address(this));

        // The winning answer is keccak256(abi.encodePacked(blockhash(target)));
        // by rolling more than 256 blocks past the target, blockhash(target) is 0,
        // so a guess of keccak256(abi.encodePacked(bytes32(0))) is guaranteed to win.
        vm.deal(actor, 1 ether);
        vm.startPrank(actor);
        c.lockInGuess{value: 1 ether}(keccak256(abi.encodePacked(bytes32(0))));
        vm.roll(block.number + 257);

        bool ok;
        try c.settle() { ok = true; } catch { ok = false; }
        vm.stopPrank();

        // Rule: with only 1 ether held, settle can never complete a payout in the
        // reference contract — it always reverts for any admissible actor. The mutant
        // pays 1 ether and succeeds, leaving the balance drained.
        assertTrue(!ok && address(c).balance == 1 ether);
    }
}

