pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    // keccak256(abi.encodePacked(bytes32(0))) — the winning answer when blockhash is 0
    bytes32 constant WINNING_ANSWER = keccak256(abi.encodePacked(bytes32(0)));

    function setUp() public { c = new C{value: 1 ether}(); }

    function testFuzz_property(address actor, uint256 rollAhead) public {
        vm.assume(actor != address(0) && actor != address(c));
        vm.assume(actor.code.length == 0); // plain EOA so transfer succeeds
        rollAhead = bound(rollAhead, 257, 100000); // target blockhash unreachable => 0

        uint256 lockBlock = block.number + 1; // guesses.block is block.number + 1

        vm.deal(actor, 1 ether);
        vm.prank(actor);
        c.lockInGuess{value: 1 ether}(WINNING_ANSWER);

        vm.roll(lockBlock + rollAhead);
        vm.prank(actor);
        c.settle();

        // Winning settle pays the ENTIRE 2-ether pool: contract is drained to 0.
        // The mutant pays only 1 ether, leaving 1 ether, so this fails for it.
        assertTrue(address(c).balance == 0, "winning settle must drain the full 2-ether pool");
    }
}

