pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C{value: 1 ether}(); }

    function testFuzz_property(address actor, uint256 gap) public {
        // admissible domain: a real, non-contract external caller distinct from c
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));

        // the winning guess: the target block's hash is provably 0 when settled
        // more than 256 blocks later, so answer == keccak256(abi.encodePacked(bytes32(0)))
        bytes32 winningGuess = keccak256(abi.encodePacked(bytes32(0)));

        vm.deal(actor, 1 ether);
        vm.prank(actor);
        c.lockInGuess{value: 1 ether}(winningGuess);

        // settle far past the target block so blockhash(target) == 0 deterministically
        gap = bound(gap, 257, 1_000_000);
        vm.roll(block.number + gap);

        vm.prank(actor);
        bool ok;
        try c.settle() {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: any completed settle of a provably winning guess pays out the
        // 2-ether prize (1 ether prize pool + 1 ether stake), draining c to 0.
        assertTrue(ok && address(c).balance == 0);
    }
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function test(bytes32 h) public {
        require(address(this).balance >= 1 ether);
        bool reverted = false;
        c.lockInGuess{value: 1 ether}(h);
        assert(!reverted);
    }

    receive() external payable {}
    fallback() external payable {}
}

